import{S as e,o as n,c as t,a9 as l,B as p}from"./chunks/framework.IJ8axLs_.js";const h="/agentsrc/images/claudecode/02-startup-sequence.svg",c=JSON.parse('{"title":"Claude Code 主循环源码拆解：一个 while(true) 为什么要写七条 continue","description":"","frontmatter":{"title":"Claude Code 主循环源码拆解：一个 while(true) 为什么要写七条 continue"},"headers":[],"relativePath":"claudecode/02-mainloop.md","filePath":"claudecode/02-mainloop.md","lastUpdated":1790217011000}'),k={name:"claudecode/02-mainloop.md"},E=Object.assign(k,{setup(o){const i=[{question:"`queryLoop` 判断循环是否继续的依据是什么，为什么不用 `stop_reason`？",options:["用 stop_reason 字段，API 契约保证其可靠性","用 needsFollowUp 标志，stop_reason 流式下不可靠","用 turnCount 计数，到达默认上限即退出","用 message_stop 事件，它总是最后到达"],correct:1,explanation:"源码注释明确 stop_reason === tool_use 在流式场景设置不一致，不可靠。CC 改用 needsFollowUp 布尔标志：流式处理中看到 tool_use 块就置位，流结束后为 false 才终止。判定依据从模型声明的结束原因换成模型实际发出的动作。"},{question:"stop_hook_blocking 路径必须保持 hasAttemptedReactiveCompact 标志，原因是？",options:["保持 TypeScript 类型系统对 State 的完备性检查","避免向遥测系统重复上报压缩事件","防止压缩失败后重试陷入死循环烧掉大量 API 调用","让 stop hook 能识别上一轮的压缩产物格式"],correct:2,explanation:"重置为 false 会导致：压缩 → 还是太长 → 错误 → stop hook 阻断 → 再压缩 → ……的死循环，注释记录曾烧掉数千次 API 调用。保持标志让 stop-hook 阻断路径不再触发已失败的压缩，这是路径间协调机制。"},{question:"StreamingToolExecutor 带来的核心改变是？",options:["把多个工具的执行从串行改为完全并行","工具在模型流式输出过程中就开始执行","将工具结果缓存后批量回填给下一次请求","把权限检查移到工具执行完成之后进行"],correct:1,explanation:"tool_use 块一到就 addTool 注册执行，getCompletedResults 同步弹出已完成结果——模型输出第 3 个工具块时前 2 个可能已执行完。压掉的是「模型说完才动手」的串行等待；工具并发仍按 isConcurrencySafe 分区、权限检查也仍在前。"},{question:"模型还在跑一个 turn，用户又输入了一句普通文本，CC 的处理是？",options:["立即中断当前 turn，新输入优先处理","排队等待，turn 内作为附件回灌给模型","直接丢弃，提示用户等待当前任务完成","暂停流式响应，等用户确认后再继续"],correct:1,explanation:"queryGuard.tryStart() 返回 null 时输入进统一队列（now > next > later），不打断。turn 内每轮工具执行后，queryLoop 把排队输入变成 attachment 塞进 toolResults 回灌（query.ts:1570-1590），turn 结束后 useQueueProcessor 冲刷剩余项。只有 now 优先级才触发 abort；斜杠命令不参与 turn 内回灌，等 turn 结束走自己的管线。"},{question:"可恢复错误（如 prompt-too-long）在流式过程中被「扣留」，这个设计的边界是什么？",options:["扣留有 10 次上限，超过后强制 yield 给用户","恢复失败时错误消息会随 result 消息一起返回","恢复路径有 bug 时用户可能看不到中间错误","扣留只对 max_output_tokens 类错误生效"],correct:2,explanation:"扣留后先试恢复：成功则用户无感，失败才 yield 错误。代价是恢复路径自身有 bug 时外部完全看不到中间错误，只能靠 transition.reason 在日志和测试里追踪。扣留覆盖 prompt-too-long、媒体超限和 max-output-tokens，且扣留侧与恢复侧的 gate 必须同值，否则消息会凭空消失。"}];return(d,s)=>{const a=e("Quiz");return n(),t("div",null,[s[0]||(s[0]=l("",104)),p(a,{questions:i})])}}});export{c as __pageData,E as default};
